```js
const client = new (require('redwood-js')).Redwood({ apiKey: process.env.REDWOOD_KEY })
async function genWithBackoff(req){
  let a=0
  while(a<6){
    try{ return await client.generate(req) }catch(err){
      if(err.status===429){
        const ra = Number(err.headers?.['retry-after']) || (2**a)
        await new Promise(r=>setTimeout(r, Math.random()*ra*1000))
        a++
        continue
      }
      throw err
    }
  }
}
```
